#!/bin/bash
# Receipt for an order: bin/receipt <cents> [guest]
cd "$(dirname "$0")/.." || exit 1
source lib/receipt/line.sh
if [ "$2" = guest ]; then guest_line "$1"; else member_line "$1"; fi

#!/bin/bash
# Receipt lines. The member line shows the member price (10% off, rounded down).
source "$(dirname "$0")/../lib/util/money.sh" 2>/dev/null || source lib/util/money.sh
member_line() { echo "receipt $(round_tenth "$1")"; }
guest_line() { echo "receipt $1"; }

./README.md:2:Member price: 10% off, rounded down. Used by `bin/price`, `bin/quote` and `lib/invoice.sh`.
./tests/price_test.sh:3:[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
./tests/price_test.sh:4:[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
./.github-cache/issue-61.md:1:PRC-412: `bin/price 999` prints 900. Members should get 899 (10% off, rounded down).
# *.[oa]
# *~

